mapper.select:
SELECT PORTFOLIO_ID AS id, PORTFOLIO_NAME AS text FROM PTL_PORTFOLIO WHERE PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01}
AND PORTFOLIO_ID = #{initValue}
AND (PORTFOLIO_ID LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%') OR PORTFOLIO_NAME LIKE CONCAT(CONCAT('%',#{search,jdbcType=VARCHAR}),'%'))
AND (PTL_PORTFOLIO.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR PTL_PORTFOLIO.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))

SELECT T.PORTFOLIO_ID AS id, T.PORTFOLIO_NAME AS name, T.PROFIT_TYPE AS pId FROM PTL_PORTFOLIO T
T.PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01}
#{item}
AND T.MDATE = TO_DATE(#{mdate},'yyyy-MM-dd')
AND (T.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR T.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))

select * from ( SELECT T.portfolioId,T.portfolioName,T.assetType,T.finprodMarketId, T.isRight, T.finprodName,T.chlId,T.chlName,T.secAcctId,T.secAcctName,T.vdate,T.mdate, T.ps,T.days,T.yield,T.amount,T.printAmt,T.posAmt,T.finprodType2,T.finprodId,T.profitType,T.tradeId,T.calendarId,T.ccy,T.invAim,T.backLendDirection FROM (
/** 债券、计划类、基金、存款、项目类、股票 **/ SELECT PTL_SEC_POSITION.PORTFOLIO_ID AS portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME AS portfolioName, FIN_PRODUCT_TYPE.TYPE_8 AS assetType, FIN_PRODUCT.FINPROD_MARKET_ID AS finprodMarketId, FIN_PRODUCT.IS_RIGHT AS isRight, STL_SEC_ACCT_INFO.SEC_ACCT_ID AS secAcctId, NVL(FIN_PRODUCT.FINPROD_ABBR,FIN_PRODUCT.FINPROD_NAME) finprodName,
null AS chlId, null AS chlName, STL_SEC_ACCT_INFO.SEC_ACCT_NAME AS secAcctName, FIN_PRODUCT.VDATE AS vdate, FIN_PRODUCT.MDATE AS mdate, null AS ps, (FIN_PRODUCT.MDATE - TO_DATE(#{searchDate},'yyyy-MM-dd')) AS days, (CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F05},#{PINAN_ASSET_TYPE_F06},#{PINAN_ASSET_TYPE_F03}) THEN ROUND(NVL(YIELD.YIELD * 100, 0),4) ELSE NULL END) AS yield, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F01}) THEN ROUND((NVL(PTL_SEC_POSITION.AMOUNT * 100, 0)), 2) ELSE NULL END AS amount, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F05},#{PINAN_ASSET_TYPE_F06},#{PINAN_ASSET_TYPE_F03}) THEN ROUND((NVL(PTL_SEC_POSITION.AMOUNT, 0)), 2) ELSE NULL END AS printAmt, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F11},#{PINAN_ASSET_TYPE_F04},#{PINAN_ASSET_TYPE_F09}) THEN ROUND((NVL(PTL_SEC_POSITION.AMOUNT, 0)), 2) ELSE NULL END AS posAmt, FIN_PRODUCT.FINPROD_TYPE2 AS finprodType2, FIN_PRODUCT.FINPROD_ID AS finprodId, FIN_PRODUCT.PROFIT_TYPE AS profitType, null AS tradeId, FIN_PRODUCT.CALENDAR_ID AS calendarId, FIN_PRODUCT.CCY AS ccy, PTL_SEC_POSITION.INV_AIM AS invAim, NULL AS backLendDirection FROM PTL_SEC_POSITION INNER JOIN PTL_PORTFOLIO ON PTL_SEC_POSITION.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID INNER JOIN FIN_PRODUCT ON PTL_SEC_POSITION.FINPROD_ID = FIN_PRODUCT.FINPROD_ID INNER JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID INNER JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT_TYPE.FINPROD_ID = FIN_PRODUCT.FINPROD_ID AND FIN_PRODUCT_TYPE.TYPE_8 IS NOT NULL AND FIN_PRODUCT_TYPE.BRANCH = 0
LEFT JOIN STL_SEC_ACCT_INFO on STL_SEC_ACCT_INFO.SEC_ACCT_ID = PTL_SEC_POSITION.SEC_ACCT_ID AND PTL_SEC_POSITION.SEC_ACCT_ID != '999999' LEFT JOIN () YIELD ON YIELD.FINPROD_ID = PTL_SEC_POSITION.FINPROD_ID WHERE PTL_SEC_POSITION.HODING_TYPE = #{POSITION_TYPE_03} AND PTL_SEC_POSITION.CDATE = TO_DATE(#{searchDate},'yyyy-MM-dd')
#{item}
AND (PTL_PORTFOLIO.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR PTL_PORTFOLIO.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
AND PTL_PORTFOLIO.PORTFOLIO_ID = #{portfolioCode,jdbcType=VARCHAR}
and ( FIN_PRODUCT.FINPROD_TYPE2 = 'F01' or (FIN_PRODUCT.FINPROD_TYPE2 in ('F07','F17','F18') and FIN_PRODUCT_ADD.IS_INNER_ADV = 'Y') or (FIN_PRODUCT.FINPROD_TYPE2 = 'F06' and FIN_PRODUCT.TRADE_MARKET = '09' and FIN_PRODUCT_ADD.IS_INNER_ADV = 'Y') or (FIN_PRODUCT.FINPROD_TYPE2 = 'F06' and FIN_PRODUCT.TRADE_MARKET != '09') )
)T WHERE (T.amount > 0 OR T.printAmt > 0 OR T.posAmt > 0) and ((T.assetType != 'F02' AND T.days >=0) OR T.assetType = 'F02') ORDER BY T.assetType,T.portfolioId,T.finprodId )
#{item}

SELECT DISTINCT
T.status,T.totleTradeId,T.tradeId,T.portfolioId,T.portfolioName,T.assetType,T.finprodId,T.finprodMarketId,T.finprodName,T.chlId,T.chlName,
T.tradeDate,T.ps,T.tradeMarket,T.ccy,T.netPrice,T.yield,T.amount,T.printAmt,T.tradeAmt,T.type6,T.backLendDirection

,T.finprodType2

FROM (
/** 债券、存款、项目类、计划类、基金、股票 **/

/** 债券质押式 **/

/** 债券借贷 **/
UNION ALL

/** 买断式回购 **/

/** 拆借 **/

)T 
ORDER BY T.status,T.assetType,T.portfolioId,T.finprodMarketId

mapper.sql:
/** 有效或撤销 **/
SELECT CASE WHEN (TRD_PRODUCT_DEAL.IS_CANCEL IS NULL OR TRD_PRODUCT_DEAL.IS_CANCEL = 'N') THEN #{TRADE_STATUS_02} ELSE #{TRADE_STATUS_03} END AS status, TRD_PRODUCT_DEAL.TOTLE_TRADE_ID AS totleTradeId, decode(FIN_PRODUCT_TYPE.TYPE_8,'F03',TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,'F01',TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,'F06',TRD_PRODUCT_DEAL.TOTLE_TRADE_ID, TRD_PRODUCT_DEAL.TRADE_ID) AS tradeId, TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID AS portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME AS portfolioName, FIN_PRODUCT_TYPE.TYPE_8 AS assetType, FIN_PRODUCT.FINPROD_ID AS finprodId, FIN_PRODUCT.FINPROD_MARKET_ID AS finprodMarketId, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F01}) THEN FIN_PRODUCT.FINPROD_ABBR ELSE FIN_PRODUCT.FINPROD_NAME END AS finprodName, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F06}) THEN CHLFIN_PRODUCT1.FINPROD_ID ELSE CHLFIN_PRODUCT.FINPROD_ID END AS chlId, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F06}) THEN CHLFIN_PRODUCT1.FINPROD_NAME ELSE CHLFIN_PRODUCT.FINPROD_NAME END AS chlName, TRD_PRODUCT_DEAL.SETTLE_DATE AS tradeDate, TRD_PRODUCT_DEAL.PS AS ps, TRD_PRODUCT_DEAL.TRADE_MARKET AS tradeMarket, TRD_PRODUCT_DEAL.CCY AS ccy, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F04}, #{PINAN_ASSET_TYPE_F11}) THEN TRD_PRODUCT_DEAL.UNIT_CPRICE ELSE NULL END AS netPrice, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F05},#{PINAN_ASSET_TYPE_F06}) THEN ROUND(NVL(YIELD.YIELD * 100, 0),2) WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F03}) THEN ROUND(NVL(YIELD.YIELD * 100, 0),2) WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F01}) THEN ROUND(NVL((CASE WHEN FIN_PRODUCT.IS_RIGHT = 'Y' THEN TRD_PRODUCT_DEAL.EXER_YIELD ELSE TRD_PRODUCT_DEAL.YIELD END) * 100, 0),2)/*modify by jiangpeng on 20210512 ZGBSSE-258*/ ELSE NULL END AS yield, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F01}) THEN ROUND(NVL(TRD_PRODUCT_DEAL.SHARE_AMT * 100, 0), 2) ELSE NULL END AS amount, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F05},#{PINAN_ASSET_TYPE_F06}) THEN ROUND(NVL(TRD_PRODUCT_DEAL.PRIN_AMT, 0)) WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F08}) THEN ROUND(NVL(TRD_PRODUCT_DEAL.PRIN_AMT, 0)) ELSE NULL END AS printAmt, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F11}) THEN ROUND(NVL(TRD_PRODUCT_DEAL.SHARE_AMT, 0)) WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F04},#{PINAN_ASSET_TYPE_F09}) THEN ROUND(NVL(TRD_PRODUCT_DEAL.SHARE_AMT, 0)) ELSE NULL END AS tradeAmt, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 = #{PINAN_ASSET_TYPE_F08} THEN FIN_PRODUCT_TYPE.TYPE_6 ELSE null END as type6, NULL as backLendDirection
,TRD_PRODUCT_DEAL.FINPROD_TYPE2 as finprodType2
,TRD_PRODUCT_DEAL.IS_SWAP_TRANSACTION AS isSwapTransaction FROM TRD_PRODUCT_DEAL LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL on TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = TRD_PRODUCT_DEAL.TOTLE_TRADE_ID AND TRD_FIN_PRODUCT_DEAL_TOTAL.PS = TRD_PRODUCT_DEAL.PS LEFT JOIN TRD_PRODUCT_DEAL_ADD ON TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL_ADD.TRADE_ID LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID LEFT JOIN FIN_PRODUCT CHLFIN_PRODUCT ON CHLFIN_PRODUCT.IS_CHL = #{YESORNO_Y} AND CHLFIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.CHL_ID LEFT JOIN FIN_PRODUCT CHLFIN_PRODUCT1 ON CHLFIN_PRODUCT1.IS_CHL = #{YESORNO_Y} AND CHLFIN_PRODUCT1.FINPROD_ID = TRD_FIN_PRODUCT_DEAL_TOTAL.CHL_ID LEFT JOIN () YIELD ON YIELD.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID WHERE PTL_PORTFOLIO.PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01} AND TRD_PRODUCT_DEAL.TRADE_STATUS != '03' AND TRD_PRODUCT_DEAL.IS_OUT_TRADE = #{YESORNO_N} AND TRD_PRODUCT_DEAL.IS_SWAP_TRANSACTION = #{YESORNO_Y}
#{item}
AND (PTL_PORTFOLIO.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR PTL_PORTFOLIO.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
#{item}
AND TRD_PRODUCT_DEAL.IS_CANCEL != 'Y'
AND TRD_PRODUCT_DEAL.IS_CANCEL = 'Y'
AND TRD_PRODUCT_DEAL.SETTLE_DATE = TO_DATE(#{tradeDate},'yyyy-MM-dd')
AND TRD_PRODUCT_DEAL.TRADE_ID LIKE CONCAT(CONCAT('%',#{tradeId,jdbcType=VARCHAR}),'%')
#{item}
AND FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F04}, #{PINAN_ASSET_TYPE_F09}, #{PINAN_ASSET_TYPE_F11},#{PINAN_ASSET_TYPE_F05},#{PINAN_ASSET_TYPE_F06},#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F08})
UNION ALL /** 流程中 **/
SELECT '${TRADE_STATUS_01}' AS status, WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID AS totleTradeId, decode(FIN_PRODUCT_TYPE.TYPE_8,'F03',WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,'F01',WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID,'F06',WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID, WFL_TRD_PRODUCT_DEAL.TRADE_ID) AS tradeId, WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID AS portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME AS portfolioName, FIN_PRODUCT_TYPE.TYPE_8 AS assetType, FIN_PRODUCT.FINPROD_ID AS finprodId, FIN_PRODUCT.FINPROD_MARKET_ID AS finprodMarketId, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F01}) THEN FIN_PRODUCT.FINPROD_ABBR ELSE FIN_PRODUCT.FINPROD_NAME END AS finprodName, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F06}) THEN CHLFIN_PRODUCT1.FINPROD_ID ELSE CHLFIN_PRODUCT.FINPROD_ID END AS chlId, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F06}) THEN CHLFIN_PRODUCT1.FINPROD_NAME ELSE CHLFIN_PRODUCT.FINPROD_NAME END AS chlName, WFL_TRD_PRODUCT_DEAL.SETTLE_DATE AS tradeDate, WFL_TRD_PRODUCT_DEAL.PS AS ps, WFL_TRD_PRODUCT_DEAL.TRADE_MARKET AS tradeMarket, WFL_TRD_PRODUCT_DEAL.CCY AS ccy, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F04}, #{PINAN_ASSET_TYPE_F11}) THEN WFL_TRD_PRODUCT_DEAL.UNIT_CPRICE ELSE NULL END AS netPrice, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F05},#{PINAN_ASSET_TYPE_F06}) THEN ROUND(NVL(YIELD.YIELD * 100, 0),2) WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F03}) THEN ROUND(NVL(YIELD.YIELD * 100, 0),2) WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F01}) THEN ROUND( NVL((CASE WHEN FIN_PRODUCT.IS_RIGHT = 'Y' THEN WFL_TRD_PRODUCT_DEAL.EXER_YIELD ELSE WFL_TRD_PRODUCT_DEAL.YIELD END) * 100, 0),2)/*modify by jiangpeng on 20210512 ZGBSSE-258*/ ELSE NULL END AS yield, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F01}) THEN ROUND(NVL(WFL_TRD_PRODUCT_DEAL.SHARE_AMT * 100, 0), 2) ELSE NULL END AS amount, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F05},#{PINAN_ASSET_TYPE_F06}) THEN ROUND(NVL(WFL_TRD_PRODUCT_DEAL.PRIN_AMT, 0)) WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F03}) THEN ROUND(NVL(WFL_TRD_PRODUCT_DEAL.PRIN_AMT, 0)) ELSE NULL END AS printAmt, CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F11}) THEN ROUND(NVL(WFL_TRD_PRODUCT_DEAL.SHARE_AMT, 0)) WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F04},#{PINAN_ASSET_TYPE_F09}) THEN ROUND(NVL(WFL_TRD_PRODUCT_DEAL.SHARE_AMT, 0)) ELSE NULL END AS tradeAmt, null as type6, NULL as backLendDirection
,WFL_TRD_PRODUCT_DEAL.FINPROD_TYPE2 as finprodType2
,WFL_TRD_PRODUCT_DEAL.IS_SWAP_TRANSACTION AS isSwapTransaction FROM WFL_TRD_PRODUCT_DEAL LEFT JOIN WFL_TRD_FIN_PRODUCT_DEAL_TOTAL on WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.TOTLE_TRADE_ID = WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID AND WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.PS = WFL_TRD_PRODUCT_DEAL.PS LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD ON WFL_TRD_PRODUCT_DEAL.TRADE_ID = WFL_TRD_PRODUCT_DEAL_ADD.TRADE_ID LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = WFL_TRD_PRODUCT_DEAL.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID LEFT JOIN FIN_PRODUCT CHLFIN_PRODUCT ON CHLFIN_PRODUCT.IS_CHL = #{YESORNO_Y} AND CHLFIN_PRODUCT.FINPROD_ID = WFL_TRD_PRODUCT_DEAL.CHL_ID LEFT JOIN FIN_PRODUCT CHLFIN_PRODUCT1 ON CHLFIN_PRODUCT1.IS_CHL = #{YESORNO_Y} AND CHLFIN_PRODUCT1.FINPROD_ID = WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.CHL_ID LEFT JOIN () YIELD ON YIELD.FINPROD_ID = WFL_TRD_PRODUCT_DEAL.FINPROD_ID WHERE PTL_PORTFOLIO.PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01} AND WFL_TRD_PRODUCT_DEAL.IS_OUT_TRADE = #{YESORNO_N} AND WFL_TRD_PRODUCT_DEAL.IS_SWAP_TRANSACTION = #{YESORNO_Y}
#{item}
AND (PTL_PORTFOLIO.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR PTL_PORTFOLIO.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
#{item}
AND WFL_TRD_PRODUCT_DEAL.SETTLE_DATE = TO_DATE(#{tradeDate},'yyyy-MM-dd')
AND WFL_TRD_PRODUCT_DEAL.TRADE_ID LIKE CONCAT(CONCAT('%',#{tradeId,jdbcType=VARCHAR}),'%')
#{item}
AND FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F04}, #{PINAN_ASSET_TYPE_F09}, #{PINAN_ASSET_TYPE_F11},#{PINAN_ASSET_TYPE_F05},#{PINAN_ASSET_TYPE_F06},#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F08})

/** 有效或撤销 **/
SELECT CASE WHEN (TRD_PRODUCT_DEAL.IS_CANCEL IS NULL OR TRD_PRODUCT_DEAL.IS_CANCEL = 'N') THEN #{TRADE_STATUS_02} ELSE #{TRADE_STATUS_03} END AS status, TRD_PRODUCT_DEAL.TOTLE_TRADE_ID AS totleTradeId, TRD_PRODUCT_DEAL.TRADE_ID AS tradeId, TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID AS portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME AS portfolioName, FIN_PRODUCT_TYPE.TYPE_8 AS assetType, NULL AS finprodId, NULL AS finprodMarketId, NULL AS finprodName, CHLFIN_PRODUCT.FINPROD_ID AS chlId, CHLFIN_PRODUCT.FINPROD_NAME AS chlName, TRD_PRODUCT_DEAL.SETTLE_DATE AS tradeDate, TRD_PRODUCT_DEAL.PS AS ps, TRD_PRODUCT_DEAL.TRADE_MARKET AS tradeMarket, TRD_PRODUCT_DEAL.CCY AS ccy, NULL AS netPrice, ROUND(NVL(FIN_TRADE_PRODUCT.INT_RATE * 100, 0), 2) AS yield, NULL AS amount, TRD_PRODUCT_DEAL.PRIN_AMT AS printAmt, NULL AS tradeAmt, FIN_PRODUCT_TYPE.TYPE_6 as type6, NULL as backLendDirection
,TRD_PRODUCT_DEAL.FINPROD_TYPE2 as finprodType2
,TRD_PRODUCT_DEAL.IS_SWAP_TRANSACTION AS isSwapTransaction FROM TRD_PRODUCT_DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD ON TRD_PRODUCT_DEAL.TRADE_ID = TRD_PRODUCT_DEAL_ADD.TRADE_ID LEFT JOIN PTL_PORTFOLIO ON PTL_PORTFOLIO.PORTFOLIO_ID = TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT ON FIN_TRADE_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_TRADE_PRODUCT.BRANCH = TRD_PRODUCT_DEAL.BRANCH LEFT JOIN FIN_PRODUCT_TYPE ON FIN_PRODUCT_TYPE.FINPROD_ID = FIN_TRADE_PRODUCT.FINPROD_ID AND FIN_PRODUCT_TYPE.BRANCH = FIN_TRADE_PRODUCT.BRANCH LEFT JOIN FIN_PRODUCT CHLFIN_PRODUCT ON CHLFIN_PRODUCT.IS_CHL = #{YESORNO_Y} AND CHLFIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.CHL_ID LEFT JOIN PA_TRD_PRODUCT_DEAL ON TRD_PRODUCT_DEAL.TRADE_ID = PA_TRD_PRODUCT_DEAL.TRADE_ID WHERE PTL_PORTFOLIO.PORTFOLIO_TYPE = #{PORTFOLIO_TYPE_01} AND TRD_PRODUCT_DEAL.TRADE_STATUS != '03' AND TRD_PRODUCT_DEAL.IS_OUT_TRADE = #{YESORNO_N} AND TRD_PRODUCT_DEAL.IS_SWAP_TRANSACTION = #{YESORNO_Y}
#{item}
AND (PTL_PORTFOLIO.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}) OR PTL_PORTFOLIO.PARENT_PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{userId}))
#{item}
AND TRD_PRODUCT_DEAL.IS_CANCEL != 'Y'
AND TRD_PRODUCT_DEAL.IS_CANCEL = 'Y'
AND TRD_PRODUCT_DEAL.SETTLE_DATE = TO_DATE(#{tradeDate},'yyyy-MM-dd')
AND TRD_PRODUCT_DEAL.TRADE_ID LIKE CONCAT(CONCAT('%',#{tradeId,jdbcType=VARCHAR}),'%')
#{item}
AND FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F07})
UNION ALL /** 流程中 **/
SELECT '${TRADE_STATUS_01}' AS status, WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID AS totleTradeId, WFL_TRD_PRODUCT_DEAL.TRADE_ID AS tradeId, WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID AS portfolioId, PTL_PORTFOLIO.PORTFOLIO_NAME AS portfolioName, FIN_PRODUCT_TYPE.TYPE_8 AS assetType, NULL AS finprodId, NULL AS finprodMarketId, NULL AS finprodName, CHLFIN_PRODUCT.FINPROD_ID AS chlId, CHLFIN_PRODUCT.FINPROD_NAME AS chlName, WFL_TRD_PRODUCT_DEAL.SETTLE_DATE AS tradeDate, WFL_TRD_PRODUCT_DEAL.PS AS ps, WFL_TRD_PRODUCT_DEAL.TRADE_MARKET AS tradeMarket, WFL_TRD_PRODUCT_DEAL.CCY AS ccy, NULL AS netPrice, ROUND(NVL(FIN_TRADE_PRODUCT.INT_RATE * 100, 0), 2) AS yield, NULL AS amount, WFL_TRD_PRODUCT_DEAL.PRIN_AMT AS printAmt, NULL AS tradeAmt, FIN_PRODUCT_TYPE.TYPE_6 as type6, NULL as backLendDirection
,WFL_TRD_PRODUCT_DEAL.FINPROD_TYPE2 as finprodType2
