    AND SEC_ACCT_ID = #{secAcctId}


    AND FINPROD_ID = #{finprodId}


    AND INV_AIM = #{invAim}


    AND CCY = #{ccy}

SELECT DISTINCT NVL(T.AMT,0) FROM ( SELECT SUM(NVL(CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 = #{PINAN_ASSET_TYPE_F01} THEN WFL_TRD_PRODUCT_DEAL.SHARE_AMT*100 WHEN FIN_PRODUCT_TYPE.TYPE_8 in (#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F06},#{PINAN_ASSET_TYPE_F05}) THEN WFL_TRD_PRODUCT_DEAL.PRIN_AMT ELSE NULL END, 0)) AMT, WFL_TRD_PRODUCT_DEAL.FINPROD_ID, WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, WFL_TRD_PRODUCT_DEAL.CHL_ID, WFL_TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, WFL_TRD_PRODUCT_DEAL.CCY, WFL_TRD_PRODUCT_DEAL.INV_AIM FROM WFL_TRD_PRODUCT_DEAL LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD ON WFL_TRD_PRODUCT_DEAL.TRADE_ID = WFL_TRD_PRODUCT_DEAL_ADD.TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE ON WFL_TRD_PRODUCT_DEAL.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID WHERE WFL_TRD_PRODUCT_DEAL.TRADE_DATE <= TO_DATE(#{searchDate},'yyyy-MM-dd') AND FIN_PRODUCT_TYPE.TYPE_8 in (#{PINAN_ASSET_TYPE_F01},#{PINAN_ASSET_TYPE_F03},#{PINAN_ASSET_TYPE_F06},#{PINAN_ASSET_TYPE_F05}) AND WFL_TRD_PRODUCT_DEAL.IS_OUT_TRADE = 'N' AND WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID IS NULL AND WFL_TRD_PRODUCT_DEAL.PS = #{PS_T01} GROUP BY WFL_TRD_PRODUCT_DEAL.FINPROD_ID, WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, WFL_TRD_PRODUCT_DEAL.CHL_ID, WFL_TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, WFL_TRD_PRODUCT_DEAL.CCY, WFL_TRD_PRODUCT_DEAL.INV_AIM
UNION ALL
SELECT SUM(NVL(CASE WHEN WFL_TRD_PRODUCT_DEAL.PS = #{PS_T01} THEN (CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F04},#{PINAN_ASSET_TYPE_F02}) THEN WFL_TRD_PRODUCT_DEAL.SHARE_AMT WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F07},#{PINAN_ASSET_TYPE_F10},#{PINAN_ASSET_TYPE_F08}) THEN WFL_TRD_PRODUCT_DEAL.PRIN_AMT ELSE NULL END) ELSE -1 * (CASE WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F04},#{PINAN_ASSET_TYPE_F02}) THEN WFL_TRD_PRODUCT_DEAL.SHARE_AMT WHEN FIN_PRODUCT_TYPE.TYPE_8 IN (#{PINAN_ASSET_TYPE_F07},#{PINAN_ASSET_TYPE_F10},#{PINAN_ASSET_TYPE_F08}) THEN WFL_TRD_PRODUCT_DEAL.PRIN_AMT ELSE NULL END) END, 0)) AMT, WFL_TRD_PRODUCT_DEAL.FINPROD_ID, WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, WFL_TRD_PRODUCT_DEAL.CHL_ID, WFL_TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, WFL_TRD_PRODUCT_DEAL.CCY, WFL_TRD_PRODUCT_DEAL.INV_AIM FROM WFL_TRD_PRODUCT_DEAL LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD ON WFL_TRD_PRODUCT_DEAL.TRADE_ID = WFL_TRD_PRODUCT_DEAL_ADD.TRADE_ID LEFT JOIN FIN_PRODUCT_TYPE ON WFL_TRD_PRODUCT_DEAL.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID WHERE WFL_TRD_PRODUCT_DEAL.TRADE_DATE <= TO_DATE(#{searchDate},'yyyy-MM-dd') AND FIN_PRODUCT_TYPE.TYPE_8 in (#{PINAN_ASSET_TYPE_F04},#{PINAN_ASSET_TYPE_F02},#{PINAN_ASSET_TYPE_F08},#{PINAN_ASSET_TYPE_F07},#{PINAN_ASSET_TYPE_F10}) AND WFL_TRD_PRODUCT_DEAL.IS_OUT_TRADE = 'N' AND WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID IS NULL AND WFL_TRD_PRODUCT_DEAL.PS IN (#{PS_T01}, #{PS_T02}) GROUP BY WFL_TRD_PRODUCT_DEAL.FINPROD_ID, WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID, WFL_TRD_PRODUCT_DEAL.CHL_ID, WFL_TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, WFL_TRD_PRODUCT_DEAL.CCY, WFL_TRD_PRODUCT_DEAL.INV_AIM
UNION ALL
SELECT SUM(NVL( -1 * WFL_TRD_PRODUCT_DEAL.SHARE_AMT , 0)*100) AMT, WFL_TRD_PRODUCT_DEAL.FINPROD_ID, WFL_TRD_PRODUCT_DEAL.COUNTER_ID AS PORTFOLIO_ID, WFL_TRD_PRODUCT_DEAL.CHL_ID, WFL_TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, WFL_TRD_PRODUCT_DEAL.CCY, WFL_TRD_PRODUCT_DEAL.INV_AIM FROM WFL_TRD_PRODUCT_DEAL LEFT JOIN FIN_PRODUCT_TYPE ON WFL_TRD_PRODUCT_DEAL.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID WHERE WFL_TRD_PRODUCT_DEAL.TRADE_DATE <= TO_DATE(#{searchDate},'yyyy-MM-dd') AND FIN_PRODUCT_TYPE.TYPE_8 = #{PINAN_ASSET_TYPE_F01} AND WFL_TRD_PRODUCT_DEAL.IS_OUT_TRADE = 'N' AND WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID IS NULL AND WFL_TRD_PRODUCT_DEAL.PS = #{PS_T01} AND WFL_TRD_PRODUCT_DEAL.COUNTER_ID IS NOT NULL GROUP BY WFL_TRD_PRODUCT_DEAL.FINPROD_ID,WFL_TRD_PRODUCT_DEAL.COUNTER_ID, WFL_TRD_PRODUCT_DEAL.CHL_ID, WFL_TRD_PRODUCT_DEAL.SEC_MANAGE_ACCT_ID, WFL_TRD_PRODUCT_DEAL.CCY, WFL_TRD_PRODUCT_DEAL.INV_AIM) T
AND T.PORTFOLIO_ID = #{portfolioId}
AND T.SEC_MANAGE_ACCT_ID = #{secAcctId}
AND T.FINPROD_ID = #{finprodId}
AND nvl(T.INV_AIM,'999999') = #{invAim}
AND T.CCY = #{ccy}
AND T.CHL_ID = #{chlId}

select distinct * from ( SELECT f1.FINPROD_MARKET_ID id, nvl(f1.FINPROD_ABBR,f1.FINPROD_NAME) text FROM FIN_PRODUCT f1 inner join FIN_PRODUCT_TYPE f2 on f1.FINPROD_ID=f2.FINPROD_ID and f2.type_8 IS NOT NULL inner join FIN_PRODUCT_ADD f3 on f1.FINPROD_ID=f3.FINPROD_ID WHERE f1.FINPROD_TYPE2 in ('F01','F06','F07','F17','F18') and ( f1.FINPROD_TYPE2 = 'F01' or (f1.FINPROD_TYPE2 in ('F07','F17','F18') and f3.IS_INNER_ADV = 'Y') or (f1.FINPROD_TYPE2 = 'F06' and f1.TRADE_MARKET = '09' and f3.IS_INNER_ADV = 'Y') or (f1.FINPROD_TYPE2 = 'F06' and f1.TRADE_MARKET != '09') )
AND (f1.FINPROD_MARKET_ID LIKE CONCAT('%',CONCAT(#{search},'%')) OR f1.FINPROD_NAME LIKE CONCAT('%',CONCAT(#{search},'%')) OR f1.FINPROD_ABBR LIKE CONCAT('%',CONCAT(#{search},'%')))
and f2.type_8 in
#{item}
)

